export const DASHBOARD_CSS = ":root {\n  --blue: #2B50F0; --blue-dark: #1E3BC4; --blue-soft: #EEF1FE;\n  --ink: #1B2340; --ink-2: #3B4462; --muted: #6B7595; --muted-2: #8A93AE;\n  --line: #E6EAF4; --line-2: #DDE3F0; --bg: #F7F9FD; --card: #FFFFFF;\n  --green: #15A05A; --green-soft: #E6F6EE; --red: #D33B3B; --red-soft: #FCECEC; --gray-soft: #F1F4FB;\n}\n* { box-sizing: border-box; }\nbody { margin: 0; background: var(--bg); color: var(--ink); font: 14px/1.5 \"IBM Plex Sans Thai\", system-ui, -apple-system, \"Segoe UI\", sans-serif; }\n.mono { font-family: \"IBM Plex Mono\", ui-monospace, monospace; }\n.small { font-size: 12px; } .muted { color: var(--muted); } .nowrap { white-space: nowrap; }\n.error { color: var(--red); margin: 6px 0 0; } .pre { white-space: pre-wrap; word-break: break-word; }\nh2 { font-size: 20px; margin: 8px 0 16px; } h3 { font-size: 15px; margin: 24px 0 10px; color: var(--ink-2); }\na { color: var(--blue); }\n.topbar { display: flex; align-items: center; justify-content: space-between; padding: 14px 24px; background: var(--card); border-bottom: 1px solid var(--line); gap: 12px; flex-wrap: wrap; }\n.topbar-right { display: flex; gap: 10px; align-items: center; }\n.brand { display: flex; align-items: center; gap: 10px; }\n.logo { width: 34px; height: 34px; border-radius: 9px; background: var(--blue); color: #fff; display: grid; place-items: center; font-weight: 700; }\n.tabs { display: flex; gap: 4px; padding: 0 24px; background: var(--card); border-bottom: 1px solid var(--line); overflow-x: auto; }\n.tab { border: 0; background: none; padding: 12px 14px; font: inherit; color: var(--muted); cursor: pointer; border-bottom: 2px solid transparent; white-space: nowrap; }\n.tab.active { color: var(--blue); border-bottom-color: var(--blue); font-weight: 600; }\nmain { padding: 20px 24px 60px; max-width: 1240px; margin: 0 auto; }\n.card { background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 18px; margin-bottom: 16px; }\n.tiles { display: grid; grid-template-columns: repeat(auto-fill, minmax(170px, 1fr)); gap: 12px; }\n.tile { background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 14px 16px; }\n.tile-value { font-size: 24px; font-weight: 700; } .tile-label { color: var(--muted); font-size: 12px; }\ntable { width: 100%; border-collapse: collapse; background: var(--card); border: 1px solid var(--line); border-radius: 12px; overflow: hidden; }\nth, td { text-align: left; padding: 10px 12px; border-bottom: 1px solid var(--line); vertical-align: top; }\nth { background: var(--gray-soft); color: var(--ink-2); font-weight: 600; font-size: 12px; }\ntd.reply { max-width: 320px; }\ntable.kv th { width: 260px; background: none; }\n.badge { display: inline-block; padding: 2px 8px; border-radius: 999px; font-size: 11px; font-weight: 600; background: var(--gray-soft); color: var(--ink-2); margin: 1px 0; }\n.badge.blue { background: var(--blue-soft); color: var(--blue-dark); } .badge.green { background: var(--green-soft); color: var(--green); }\n.badge.red { background: var(--red-soft); color: var(--red); } .badge.gray { background: var(--gray-soft); color: var(--muted); }\n.btn { border: 1px solid var(--line-2); background: var(--card); color: var(--ink); padding: 8px 14px; border-radius: 8px; font: inherit; cursor: pointer; }\n.btn:hover { border-color: var(--blue); } .btn.primary { background: var(--blue); border-color: var(--blue); color: #fff; }\n.btn.primary:hover { background: var(--blue-dark); } .btn.ghost { background: transparent; }\n.btn.danger { color: var(--red); } .btn.small { padding: 4px 10px; font-size: 12px; margin-right: 4px; }\ninput, select, textarea { font: inherit; padding: 8px 10px; border: 1px solid var(--line-2); border-radius: 8px; background: #fff; color: var(--ink); width: 100%; }\ninput[type=checkbox] { width: auto; }\n.field { margin-bottom: 12px; } .field label { display: block; font-size: 12px; color: var(--ink-2); margin-bottom: 4px; font-weight: 600; }\n.hint { font-size: 12px; color: var(--muted-2); margin-top: 3px; }\n.form { max-width: 640px; } .form.inline { max-width: none; display: grid; grid-template-columns: 2fr 1fr 2fr 2fr auto; gap: 12px; align-items: end; }\n.form.inline .field { margin: 0; } .actions { display: flex; gap: 8px; margin-top: 8px; }\n.check { display: flex; gap: 8px; align-items: center; margin: 8px 0; }\n.switch { display: inline-flex; gap: 6px; align-items: center; cursor: pointer; }\n.toolbar { display: flex; gap: 10px; margin-bottom: 14px; } .toolbar .search { max-width: 320px; } .toolbar select { max-width: 160px; }\n.row-between { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; }\n.row-between select { max-width: 200px; }\n.thumb { width: 40px; height: 40px; border-radius: 8px; object-fit: cover; background: var(--gray-soft); display: block; }\n.login { min-height: 100vh; display: grid; place-items: center; padding: 16px; }\n.login-card { width: 100%; max-width: 360px; display: grid; gap: 10px; }\n.note p { color: var(--ink-2); }\n.toast { position: fixed; bottom: 20px; right: 20px; background: var(--ink); color: #fff; padding: 10px 16px; border-radius: 10px; opacity: 0; transition: opacity .2s; pointer-events: none; max-width: 360px; }\n.toast.show { opacity: 1; } .toast.err { background: var(--red); }\n@media (max-width: 760px) {\n  main { padding: 16px; } .form.inline { grid-template-columns: 1fr; }\n  table { display: block; overflow-x: auto; } th, td { min-width: 120px; }\n  .topbar, .tabs { padding-left: 16px; padding-right: 16px; }\n}\n";
